UPDATE LINE_DAILY_BATCH_JOB
SET status = 'FAILED',
    status_updated_at = CURRENT_TIMESTAMP(6),
    finished_at = CURRENT_TIMESTAMP(6),
    last_error_code = #{errorCode},
    last_error_message = #{errorMessage}
WHERE id = #{id}
  AND batch_name = #{batchName}
  AND status = 'RUNNING'
